import type { InputOptions, NullValue, OutputOptions } from "rollup";

export const inputOptions = (
  updateOptions: (options: InputOptions) => InputOptions | NullValue,
) => ({
  name: "input-options",
  options(rawOptions: InputOptions) {
    return updateOptions(rawOptions);
  },
});

export const outputOptions = (
  updateOptions: (options: OutputOptions) => OutputOptions | NullValue,
) => ({
  name: "output-options",
  outputOptions(rawOptions: OutputOptions) {
    return updateOptions(rawOptions);
  },
});
